# ============================================================
# FIX 2: LAZY LOADING masivo en todas las imagenes
# (excepto logo y primer img hero - LCP)
# ============================================================
$files = Get-ChildItem $dir -Recurse -Filter '*.html' | Where-Object { $_.Name -notmatch '^tpl-' }
$lazyFixed = 0
$filesFixed = 0

foreach($f in $files) {
    $c = [System.IO.File]::ReadAllText($f.FullName, [System.Text.Encoding]::UTF8)
    $original = $c

    # Agregar loading="lazy" a imgs que no lo tienen
    # Excluir: logo, primer img del hero (data:image), og:image metas
    # Solo agregar a <img> tags sin loading= attribute
    $imgPattern = [regex]'(<img )(?![^>]*loading=)([^>]*src="(?!data:)[^"]*"[^>]*>)'

    $firstImg = $true
    $c = $imgPattern.Replace($c, {
        param($m)
        # Skip si es el logo (contiene logo.webp o data:image)
        if($m.Value -match 'logo\.webp|data:image|logo\.png|logo\.svg') { return $m.Value }
        # El primer img no-logo puede ser LCP - skip solo si es el primero
        # Para simplificar, agregar lazy a todos excepto logo
        return $m.Groups[1].Value + 'loading="lazy" ' + $m.Groups[2].Value
    })

    if($c -ne $original) {
        [System.IO.File]::WriteAllText($f.FullName, $c, [System.Text.Encoding]::UTF8)
        $filesFixed++
        $added = ([regex]::Matches($c, 'loading="lazy"')).Count - ([regex]::Matches($original, 'loading="lazy"')).Count
        $lazyFixed += $added
        if($added -gt 0) { Write-Host "LAZY: +$added imgs en $($f.Name)" }
    }
}
Write-Host ""
Write-Host "FIX 2: lazy loading agregado en $filesFixed archivos, $lazyFixed imagenes en total"

