$hamburgerCSS = '.hamburger{display:none;flex-direction:column;justify-content:center;gap:5px;width:40px;height:40px;cursor:pointer;background:none;border:none;padding:4px;border-radius:8px;transition:background .15s}.hamburger:hover{background:#f0f4ff}.hamburger span{display:block;width:24px;height:2.5px;background:#1B4B8C;border-radius:2px;transition:all .3s ease;transform-origin:center}.hamburger.open span:nth-child(1){transform:translateY(7.5px) rotate(45deg)}.hamburger.open span:nth-child(2){opacity:0;transform:scaleX(0)}.hamburger.open span:nth-child(3){transform:translateY(-7.5px) rotate(-45deg)}.nav-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:998;backdrop-filter:blur(2px)}.nav-overlay.open{display:block}@media(max-width:900px){.hamburger{display:flex}.nav-links{display:none;position:fixed;top:0;right:0;width:280px;height:100vh;background:#fff;flex-direction:column;padding:70px 24px 32px;gap:4px;z-index:999;box-shadow:-4px 0 24px rgba(0,0,0,.15);overflow-y:auto;transition:transform .3s ease;transform:translateX(100%)}.nav-links.mobile-open{display:flex;transform:translateX(0)}.nav-links a{padding:12px 16px;border-radius:10px;font-size:1rem;color:#2C3E50;border-bottom:1px solid #f0f4f8}.nav-links .nav-cta{margin-top:12px;text-align:center;background:linear-gradient(135deg,#1ABC9C,#16A085);color:#fff;border-bottom:none}}'

$hamburgerHTML = '<button class="hamburger" id="hamburgerBtn" aria-label="Menu" aria-expanded="false"><span></span><span></span><span></span></button><div class="nav-overlay" id="navOverlay"></div>'

$hamburgerJS = '<script>(function(){var btn=document.getElementById("hamburgerBtn");var nav=document.querySelector(".nav-links");var overlay=document.getElementById("navOverlay");if(!btn||!nav)return;function openMenu(){btn.classList.add("open");nav.classList.add("mobile-open");overlay.classList.add("open");btn.setAttribute("aria-expanded","true");document.body.style.overflow="hidden";}function closeMenu(){btn.classList.remove("open");nav.classList.remove("mobile-open");overlay.classList.remove("open");btn.setAttribute("aria-expanded","false");document.body.style.overflow="";}btn.addEventListener("click",function(){btn.classList.contains("open")?closeMenu():openMenu();});overlay.addEventListener("click",closeMenu);nav.querySelectorAll("a").forEach(function(a){a.addEventListener("click",closeMenu);});})();</script>'

# Archivos a modificar: homepage + 10 landings + blog/index
$targetFiles = @(
    "$dir\index.html",
    "$dir\australia\index.html",
    "$dir\irlanda\index.html",
    "$dir\canada\index.html",
    "$dir\malta\index.html",
    "$dir\dubai\index.html",
    "$dir\nueva-zelanda\index.html",
    "$dir\reino-unido\index.html",
    "$dir\estados-unidos\index.html",
    "$dir\francia\index.html",
    "$dir\alemania\index.html",
    "$dir\blog\index.html"
)

$hamburgerCount = 0
foreach($fp in $targetFiles) {
    if(-not (Test-Path $fp)) { Write-Host "SKIP (no existe): $fp"; continue }
    $c = [System.IO.File]::ReadAllText($fp, [System.Text.Encoding]::UTF8)

    # Ya tiene hamburger?
    if($c.Contains('hamburgerBtn')) { Write-Host "YA TIENE hamburger: $fp"; continue }

    # 1. Inyectar CSS antes de </style>
    $c = $c.Replace('</style>', $hamburgerCSS + '</style>')

    # 2. Inyectar boton hamburger antes del cierre de nav-container (antes de </div></nav>)
    # Buscar el cierre del nav
    $navCloseIdx = $c.IndexOf('</div></nav>')
    if($navCloseIdx -lt 0) { $navCloseIdx = $c.IndexOf('</nav>') }
    if($navCloseIdx -ge 0) {
        $closeTag = if($c.IndexOf('</div></nav>') -ge 0) { '</div></nav>' } else { '</nav>' }
        $c = $c.Replace($closeTag, $hamburgerHTML + $closeTag)
    }

    # 3. Inyectar JS antes de </body>
    $c = $c.Replace('</body>', $hamburgerJS + '</body>')

    [System.IO.File]::WriteAllText($fp, $c, [System.Text.Encoding]::UTF8)
    $hamburgerCount++
    Write-Host "HAMBURGER: $([System.IO.Path]::GetFileName([System.IO.Path]::GetDirectoryName($fp)))\$([System.IO.Path]::GetFileName($fp))"
}
Write-Host ""
Write-Host "FIX 3: hamburger menu agregado en $hamburgerCount archivos"
